using SharpTestBench;
using Xunit;
public sealed partial class ScopeCrossTests
{
    [Fact] public void S021_ExclusionsCannotEvadeFullProductBudget()
    {var c=new FunctionalCoverage();var excluded=Enumerable.Range(0,15).Select(i=>Enumerable.Range(0,4).Select(axis=>(i&(1<<axis))==0?"zero":"one").ToArray()).ToArray();Assert.Throws<ArgumentOutOfRangeException>(()=>c.AddCross("budget",Axes(4),maximumBins:8,excluded:excluded));Assert.Empty(c.Snapshot().Points);var p=c.AddCross("budget",Axes(4),maximumBins:16,excluded:excluded);p.Sample(15);Assert.Single(p.Snapshot().Bins);Assert.Equal(100,p.Snapshot().Percent);}
    [Fact] public void S022_ZeroAndExcessiveRanksRejectWithoutRecursionOrNameReservation()
    {var c=new FunctionalCoverage();Assert.Throws<ArgumentException>(()=>c.AddCross<int>("rank",[]));var tooMany=Enumerable.Range(0,33).Select(_=>new[]{B("all",_=>true)}).ToArray();Assert.Throws<ArgumentException>(()=>c.AddCross("rank",tooMany));Assert.Empty(c.Snapshot().Points);c.AddCross("rank",Axes(1));Assert.Single(c.Snapshot().Points);}
    [Fact] public void S023_NonpositiveBudgetsAndZeroGoalRejectWithoutClassification()
    {int calls=0;CoverageBin<int>[][] axes=[[B("a",_=>{calls++;return true;})],[B("b",_=>true)],[B("c",_=>true)]];var c=new FunctionalCoverage();Assert.Equal("goal",Assert.Throws<ArgumentOutOfRangeException>(()=>c.AddCross("limits",axes,goal:0)).ParamName);foreach(int limit in new[]{0,-1,int.MinValue})Assert.Equal("maximumBins",Assert.Throws<ArgumentOutOfRangeException>(()=>c.AddCross("limits",axes,maximumBins:limit)).ParamName);Assert.Equal(0,calls);Assert.Empty(c.Snapshot().Points);var p=c.AddCross("limits",axes,goal:2,maximumBins:1);p.Sample(0);Assert.Equal(1,calls);Assert.Equal(0,p.Snapshot().Percent);}
    [Fact] public void S024_HugeMathematicalProductRejectsBeforeCellAllocation()
    {var c=new FunctionalCoverage();Assert.Equal("maximumBins",Assert.Throws<ArgumentOutOfRangeException>(()=>c.AddCross("overflow",Axes(32),maximumBins:int.MaxValue)).ParamName);Assert.Empty(c.Snapshot().Points);c.AddCross("overflow",Axes(1));Assert.Single(c.Snapshot().Points);}
    [Fact] public void S025_InvalidExclusionShapesAndDuplicateCoordinatesAreAtomic()
    {var c=new FunctionalCoverage();Action[] attempts=[()=>c.AddCross("coordinates",Axes(3),excluded:null!),()=>c.AddCross("coordinates",Axes(3),excluded:[null!]),()=>c.AddCross("coordinates",Axes(3),excluded:[["zero"]]),()=>c.AddCross("coordinates",Axes(3),excluded:[["zero","zero","unknown"]]),()=>c.AddCross("coordinates",Axes(3),excluded:[["zero",null!,"zero"]]),()=>c.AddCross("coordinates",Axes(3),excluded:[["zero","zero","zero"],["zero","zero","zero"]])];foreach(var attempt in attempts){Assert.ThrowsAny<ArgumentException>(attempt);Assert.Empty(c.Snapshot().Points);}c.AddCross("coordinates",Axes(3));Assert.Single(c.Snapshot().Points);}
    [Fact] public void S026_RemovingAllCoordinatesRejectsWithoutRegisteringEmptyPoint()
    {var c=new FunctionalCoverage();var excluded=Enumerable.Range(0,8).Select(i=>Enumerable.Range(0,3).Select(axis=>(i&(1<<axis))==0?"zero":"one").ToArray()).ToArray();Assert.Throws<ArgumentException>(()=>c.AddCross("empty",Axes(3),excluded:excluded));Assert.Empty(c.Snapshot().Points);var p=c.AddCross("empty",Axes(3));p.Sample(0);Assert.Equal(8,p.Snapshot().Bins.Length);}
    [Fact] public void S027_LengthPrefixedNamesSurviveCultureUnicodeAndJson()
    {var before=System.Globalization.CultureInfo.CurrentCulture;try{System.Globalization.CultureInfo.CurrentCulture=System.Globalization.CultureInfo.GetCultureInfo("ar-SA");CoverageBin<int>[][] axes=[[B("a:b",_=>true),B("a",_=>true)],[B("c",_=>true),B("b:c",_=>true)],[B("\0😀",_=>true)]];var p=new FunctionalCoverage().AddCross("text",axes);p.Sample(0);var names=p.Snapshot().Bins.Select(b=>b.Name).ToArray();Assert.Equal(4,names.Distinct(StringComparer.Ordinal).Count());Assert.Contains("3:a:b1:c3:\0😀",names);string json=System.Text.Json.JsonSerializer.Serialize(p.Snapshot());var roundtrip=System.Text.Json.JsonSerializer.Deserialize<CoveragePointSnapshot>(json)!;Assert.Equal(names,roundtrip.Bins.Select(b=>b.Name));Assert.Equal(100,roundtrip.Percent);}finally{System.Globalization.CultureInfo.CurrentCulture=before;}}
    sealed class OpaqueSample {public override bool Equals(object? value)=>throw new IOException("Equals");public override int GetHashCode()=>throw new IOException("hash");public override string ToString()=>throw new IOException("text");}
    [Fact] public void S028_PayloadEqualityHashAndFormattingAreNeverRequired()
    {var sample=new OpaqueSample();var axes=Enumerable.Range(0,3).Select(i=>new[]{new CoverageBin<OpaqueSample>("axis"+i,value=>ReferenceEquals(value,sample))}).ToArray();var p=new FunctionalCoverage().AddCross("opaque",axes);p.Sample(sample);Assert.Equal(1UL,p.Snapshot().Samples);Assert.Equal(100,p.Snapshot().Percent);}
    [Fact] public void S029_NullPayloadsAreClassifiedByCallerWithoutImplicitEquality()
    {CoverageBin<string?>[][] axes=[[new("null",x=>x is null),new("value",x=>x is not null)],[new("all",_=>true)],[new("null",x=>x is null),new("nonempty",x=>x is {Length:>0})]];var p=new FunctionalCoverage().AddCross("nullable",axes);p.Sample(null);p.Sample("value");p.Sample("");Assert.Equal(3UL,p.Snapshot().Samples);Assert.Equal(1UL,p.Snapshot().Unmatched);Assert.Equal(2UL,p.Snapshot().Bins.Aggregate(0UL,(sum,b)=>sum+b.Hits));Assert.Equal(50,p.Snapshot().Percent);}
    [Fact] public void S030_ForeignThreadConstructionRejectsBeforeClassificationOrRegistration()
    {var c=new FunctionalCoverage();int calls=0;CoverageBin<int>[][] axes=[[B("a",_=>{calls++;return true;})],[B("b",_=>true)],[B("c",_=>true)]];Exception? failure=null;var thread=new Thread(()=>{try{c.AddCross("owner",axes);}catch(Exception error){failure=error;}});thread.Start();thread.Join();Assert.IsType<InvalidOperationException>(failure);Assert.Equal(0,calls);Assert.Empty(c.Snapshot().Points);var p=c.AddCross("owner",axes);p.Sample(0);Assert.Equal(100,p.Snapshot().Percent);}
}
